head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > keyMoveEditMode]<br/>Tab 또는 Enter 키로 Cell 을 이동할 때 편집 모드로 변경할지 설정합니다.",
    "validation" : [
        "enterKeyMove='none','edit' 이면 Enter 키에 의해서 keyMoveEditMode 속성이 동작하지 않습니다.",
        "true 설정 시 Tab 또는 Enter 키로 Cell 을 이동할 때 Cell 이 편집 모드로 변경됩니다.",
        "false(기본값) 설정 시 Tab 또는 Enter 키로 Cell 을 이동해도 편집 모드로 변경되지 않습니다.",
        "accessibility=true 이면 keyMoveEditMode 는 true 로 동작합니다.",
        "방향키를 통한 Cell 이동 시 편집 모드 변경은 moveKeyEditMode 속성으로 설정해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 읽기
    let keyMoveEditModeVal = con_keyMoveEditMode.getValue();
    let enterKeyMoveVal = con_enterKeyMove.getValue();
    let accessibilityVal = con_accessibility.getValue();
    let moveKeyEditModeVal = con_moveKeyEditMode.getValue();

    // 동작 조건/현재 설정 라벨 생성
    $c.gcm.createLabel('label="컬럼 inputType 혼합: col1=text / col2=select / col3=secret / col4=calendar (편집형 inputType 다양화, 편집모드 진입 확인용)"', '', 'label1');
    $c.gcm.createLabel('label="현재 설정: keyMoveEditMode=' + (keyMoveEditModeVal === '' ? '미설정(기본 false)' : keyMoveEditModeVal) + ' / enterKeyMove=' + (enterKeyMoveVal === '' ? '미설정(기본 down)' : enterKeyMoveVal) + ' / accessibility=' + (accessibilityVal === '' ? '미설정(기본 false)' : accessibilityVal) + ' / moveKeyEditMode=' + (moveKeyEditModeVal === '' ? '미설정(기본 false)' : moveKeyEditModeVal) + '"', '', 'label2');

    // dataList 직접 생성 (4행)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    // 각 행 모든 컬럼에 값(빈 행 0 유지) / col1(text) / col2(select)=Y,N / col3(secret)=숫자 / col4(calendar)=날짜
    let textArr = ['Apple', 'Banana', 'Cherry', 'Date'];
    let selArr = ['Y', 'N', 'Y', 'N'];
    let secretArr = ['1234', '5678', '9012', '3456'];
    let dateArr = ['20251101', '20251102', '20251103', '20251104'];
    for (let r = 0; r < 4; r++) {
        strDl += '<w2:row>';
        strDl += '<col1><![CDATA[' + textArr[r] + ']]></col1>';
        strDl += '<col2><![CDATA[' + selArr[r] + ']]></col2>';
        strDl += '<col3><![CDATA[' + secretArr[r] + ']]></col3>';
        strDl += '<col4><![CDATA[' + dateArr[r] + ']]></col4>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // keyMoveEditMode / enterKeyMove / accessibility / moveKeyEditMode 속성 (미설정 시 속성 미부여 = 기본값)
    let keyMoveEditModeAttr = keyMoveEditModeVal === '' ? '' : 'keyMoveEditMode="' + keyMoveEditModeVal + '" ';
    let enterKeyMoveAttr = enterKeyMoveVal === '' ? '' : 'enterKeyMove="' + enterKeyMoveVal + '" ';
    let accessibilityAttr = accessibilityVal === '' ? '' : 'accessibility="' + accessibilityVal + '" ';
    let moveKeyEditModeAttr = moveKeyEditModeVal === '' ? '' : 'moveKeyEditMode="' + moveKeyEditModeVal + '" ';

    // target 생성 (컬럼 inputType 혼합: text / select / secret / calendar)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + keyMoveEditModeAttr + enterKeyMoveAttr + accessibilityAttr + moveKeyEditModeAttr + 'editModeEvent="ondblclick" dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:250px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" inputType="text" id="column1" value="text"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="column2" value="select"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="column3" value="secret"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="column4" value="calendar"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" inputType="text" dataType="text" id="col1"></w2:column>';
    strTarget += '<w2:column width="140" inputType="select" dataType="text" id="col2">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>예</w2:label><w2:value>Y</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>아니오</w2:label><w2:value>N</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '<w2:column width="140" inputType="secret" dataType="text" id="col3"></w2:column>';
    strTarget += '<w2:column width="140" inputType="calendar" dataType="date" viewType="icon" displayMode="label" calendarFormat="yyyyMMdd" displayFormat="yyyy-MM-dd" id="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // Tab / Enter / Shift+Tab / 방향키 입력 후, 이동된 Cell 위치 + 편집 모드 여부 + 키종류 자동 출력
    // (편집 모드에서는 키 이벤트가 셀 내부 편집 input 으로 가고, 그리드 onkeyup 프로퍼티 핸들러도
    //  keyMoveEditMode 동작 후 stopEvent 로 전파가 끊길 수 있으므로 document 에 capture-phase keyup
    //  리스너를 1회 등록하여 Tab/Enter/방향키 keyup 을 포착)
    if (typeof scwin.keyMoveHandler === 'function') {
        document.removeEventListener('keyup', scwin.keyMoveHandler, true);
    }
    scwin.keyMoveHandler = function (ev) {
        let key = ev && (ev.keyCode || ev.which);
        // Tab(9) / Enter(13) / 방향키(37~40) 일 때만 이동 결과 출력
        if (key !== 9 && key !== 13 && (key < 37 || key > 40)) {
            return;
        }
        // 현재 target1 그리드의 셀(또는 셀 내부 편집 input)에서 발생한 이벤트인지 확인
        // select(inputType=select) 셀 편집 시 w2selectbox 드롭다운(itemTable)은 grid DOM 밖(body)에
        // 렌더되므로 gridEl.contains() 만으로는 누락됨 → 해당 팝업은 id/class 에 grid id 가 포함되어
        // 이를 기준으로 grid 연관 이벤트로 판정
        let gridEl = document.getElementById(scwin.target1.id);
        if (!gridEl || !ev.target) {
            return;
        }
        let tgt = ev.target;
        let inGrid = gridEl.contains(tgt);
        if (!inGrid) {
            let tid = tgt.id || '';
            let tcls = (typeof tgt.className === 'string') ? tgt.className : '';
            let gid = scwin.target1.id;
            if (tid.indexOf(gid) === -1 && tcls.indexOf(gid) === -1) {
                return;
            }
        }
        let keyName = '';
        if (key === 9) {
            keyName = ev.shiftKey ? 'Shift+Tab' : 'Tab';
        } else if (key === 13) {
            keyName = ev.shiftKey ? 'Shift+Enter' : 'Enter';
        } else if (key === 37) {
            keyName = '좌(ArrowLeft)';
        } else if (key === 38) {
            keyName = '상(ArrowUp)';
        } else if (key === 39) {
            keyName = '우(ArrowRight)';
        } else {
            keyName = '하(ArrowDown)';
        }
        let row = scwin.target1.getFocusedRowIndex();
        let col = scwin.target1.getFocusedColumnIndex();
        let editing = scwin.target1.isEditing();
        wf_body_bottom.getObj("scwin").setReturnValue("[" + keyName + "] 이동된 Cell(row=" + row + ", col=" + col + ") 편집모드(isEditing)=" + editing);
    };
    document.addEventListener('keyup', scwin.keyMoveHandler, true);
}
